// HEAD lib/data/scope.ts — the two-statement form.
function getEmployeeByClerkId(clerkId: string) {
  return db.user.findUnique({ where: { clerkId }, include: { employee: true } }).then((u) => u?.employee ?? null);
}
function getUserByClerkId(clerkId: string) {
  return db.user.findUnique({ where: { clerkId }, select: { id: true, role: true, employeeId: true } });
}

/** Hours after check-in past which an open row means "forgot to clock out". */
const FORGOTTEN_CHECKOUT_HOURS = 14;

/**
 * Everything the dashboard needs, in ONE Promise.all.
 *
 * Nothing here scales with headcount: each entry is a count/groupBy the
 * database resolves, or a bounded findMany (today's attendance, today's leave,
 * six months of employee rows for the trend). The heavy lifting — headcount
 * banding and funnel conversion — runs through Phase 12's existing pure
 * functions on already-fetched rows, so this page introduces no new
 * aggregation logic and no N+1.
 */
export async function adminBefore() {
  const now = new Date();
  const today = startOfDay(now);
  const tomorrow = new Date(today.getFullYear(), today.getMonth(), today.getDate() + 1);
  const dayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const forgottenBefore = new Date(now.getTime() - FORGOTTEN_CHECKOUT_HOURS * 3_600_000);
  // Six months back, inclusive of the current one.
  const trendStart = new Date(now.getFullYear(), now.getMonth() - 5, 1);

  const range = parseRange(ymd(trendStart), ymd(now));
  if (!range.ok) throw new Error("dashboard range failed to parse");

  try {
    const [
      employees,
      roleGroups,
      openReqs,
      submittedPayroll,
      draftOffers,
      appraisalAgg,
      audit24h,
      lateToday,
      onLeaveToday,
      openRows,
      applications,
      syncFailures,
      toggles,
      dbAlive,
    ] = await Promise.all([
      // One employee fetch feeds headcount, departments AND the 6-month trend.
      db.employee.findMany({
        select: {
          id: true,
          name: true,
          employeeCode: true,
          department: true,
          active: true,
          joiningDate: true,
          offboardedAt: true,
        },
      }),
      db.user.groupBy({ by: ["role"], _count: { _all: true } }),
      db.jobRequisition.count({ where: { status: "OPEN" } }),
      db.payroll.groupBy({
        by: ["month"],
        where: { status: "SUBMITTED" },
        _count: { _all: true },
      }),
      db.offer.count({ where: { status: "DRAFT" } }),
      db.appraisalScore.aggregate({
        where: { excluded: false, finalScore: { not: null }, cycle: { published: true } },
        _avg: { finalScore: true },
        _count: { _all: true },
      }),
      db.auditLog.count({ where: { timestamp: { gte: dayAgo } } }),
      // Real attendance for TODAY — late arrivals, with shift and department.
      db.attendance.findMany({
        where: { date: { gte: today, lt: tomorrow }, lateFlag: true },
        select: {
          id: true,
          checkIn: true,
          lateMinutes: true,
          employee: {
            select: {
              name: true,
              employeeCode: true,
              department: true,
              shift: { select: { name: true, startTime: true, endTime: true } },
            },
          },
        },
        orderBy: { lateMinutes: "desc" },
        take: 10,
      }),
      // Real approved leave spanning today.
      db.leaveRequest.findMany({
        where: {
          status: "APPROVED",
          startDate: { lte: tomorrow },
          endDate: { gte: today },
        },
        select: {
          id: true,
          startDate: true,
          endDate: true,
          employee: {
            select: { name: true, employeeCode: true, department: true },
          },
        },
        orderBy: { startDate: "asc" },
        take: 10,
      }),
      db.attendance.count({
        where: { checkOut: null, checkIn: { not: null, lt: forgottenBefore } },
      }),
      db.application.findMany({
        where: { createdAt: { gte: range.range.start, lt: range.range.endExclusive } },
        select: {
          id: true,
          stage: true,
          createdAt: true,
          updatedAt: true,
          jobRequisition: { select: { department: true } },
        },
      }),
      // A role change whose Clerk sync failed leaves SESS and Clerk disagreeing
      // about someone's privileges — a real, Super-Admin-fixable condition.
      db.auditLog.count({
        where: { action: "USER_ROLE_CLERK_SYNC_FAILED", timestamp: { gte: weekAgo } },
      }),
      moduleToggleValues(),
      // The same live reachability probe the Integrations page uses.
      db
        .$queryRaw`SELECT 1`
        .then(() => true)
        .catch(() => false),
    ]);

    const reportEmployees = employees.map((e) => ({
      id: e.id,
      name: e.name,
      employeeCode: e.employeeCode,
      department: e.department,
      active: e.active,
      joiningDate: e.joiningDate,
      offboardedAt: e.offboardedAt,
    }));

    // Phase 12's function, not a reimplementation.
    const headcount = computeHeadcount(reportEmployees, range.range);
    const funnel = computeRecruitmentFunnel(
      applications.map((a) => ({
        id: a.id,
        department: a.jobRequisition.department,
        stage: a.stage,
        createdAt: a.createdAt,
        updatedAt: a.updatedAt,
      })),
    );

    // Six-month trend, using headcountOn() — the same "was employed on this
    // date" rule the reports use, so the dashboard cannot disagree with them.
    const trend = Array.from({ length: 6 }).map((_, i) => {
      const monthStart = new Date(now.getFullYear(), now.getMonth() - 5 + i, 1);
      // Measure at month END (or today for the current month) so the latest
      // point reflects reality rather than the 1st of the month.
      const measureAt =
        i === 5 ? today : new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 0);
      return {
        month: monthKey(monthStart),
        headcount: headcountOn(reportEmployees, measureAt),
      };
    });

    const submittedRows = submittedPayroll.reduce((n, g) => n + g._count._all, 0);

    return {
      error: null,
      headcount,
      funnel,
      trend,
      roleRows: roleGroups
        .map((g) => ({ role: g.role as Role, count: g._count._all }))
        .sort((a, b) => b.count - a.count),
      totalUsers: roleGroups.reduce((n, g) => n + g._count._all, 0),
      openReqs,
      submittedPayroll,
      submittedRows,
      draftOffers,
      avgAppraisal: appraisalAgg._avg.finalScore,
      appraisalCount: appraisalAgg._count._all,
      audit24h,
      lateToday,
      onLeaveToday,
      openRows,
      syncFailures,
      toggles,
      dbAlive,
    };
  } catch (err) {
    console.error("[admin/dashboard] failed:", err);
    return { error: "System statistics are unavailable right now." as const };
  }
}


export async function hrNotificationsBefore(userId: string) {
  if (!userId) return [];
  try {
    const me = await getUserByClerkId(userId);
    if (!me) return [];
    const rows = await db.notification.findMany({
      where: { recipientUserId: me.id },
      orderBy: [{ read: "asc" }, { createdAt: "desc" }],
      take: 10,
    });
    return rows.map((n) => ({
      id: n.id,
      type: n.type,
      message: n.message,
      read: n.read,
      createdAt: n.createdAt.toISOString(),
    }));
  } catch (err) {
    console.error("[hr/dashboard] notifications failed:", err);
    return [];
  }
}


export async function hrFiguresBefore() {
  const now = new Date();
  const { period } = currentPeriod(now);

  try {
    const [totals, departments] = await Promise.all([
      getHrDashboardTotals(period, ymd(now)),
      getDepartments(),
    ]);

    return {
      error: null as string | null,
      period,
      departmentCount: departments.length,
      ...totals,
    };
  } catch (err) {
    console.error("[hr/dashboard] load failed:", err);
    return {
      error: "Dashboard figures could not be loaded.",
      period,
      activeCount: 0,
      departmentCount: 0,
      presentCount: 0,
      payroll: { draft: 0, submitted: 0, finalized: 0 },
      openWarnings: 0,
      unreleasedWarnings: 0,
      idleConsentCount: 0,
      retentionExpiring: 0,
    };
  }
}


export async function managerBefore(userId: string) {
  if (!userId) return { manager: null, error: null };
  try {
    const manager = await getEmployeeByClerkId(userId);
    if (!manager) return { manager: null, error: null };

    const { period, monthStart, monthEnd } = currentPeriod();
    // ORANGE TIER (SESS_Caching_Strategy.docx §2/§4) — manager/team roster,
    // 60 s, dropped by tag on any roster or shift change. A display projection
    // of the SAME direct-reports-only query (managerId + active, single level,
    // no recursive descent) — not a wider one.
    const reports = await getTeamRoster(manager.id);
    const ids = reports.map((r) => r.id);
    const inMonth = { gte: monthStart, lt: monthEnd };
    const scope = { managerId: manager.id };

    // All set-based aggregates — independent of team size (no N+1). `own` is
    // the manager's OWN attendance (today/week/shift), batched into the same
    // round trip rather than fetched separately.
    const [totals, lates, actuals, targets, pendingApprovals, quality, own] = await Promise.all([
      db.attendance.groupBy({
        by: ["employeeId"],
        where: { employee: scope, date: inMonth },
        _count: { _all: true },
      }),
      db.attendance.groupBy({
        by: ["employeeId"],
        where: { employee: scope, date: inMonth, lateFlag: true },
        _count: { _all: true },
      }),
      db.production.groupBy({
        by: ["employeeId"],
        where: { employeeId: { in: ids }, date: inMonth },
        _sum: { unitsProduced: true },
      }),
      db.monthlyTarget.findMany({ where: { period, employeeId: { in: ids } } }),
      // ORANGE TIER (§2/§4) — pending-approvals COUNT, 60 s, invalidated the
      // moment a decision is made. Only the number is cached; the list of
      // requests the manager acts on is read fresh on /manager/attendance, and
      // the decision itself is gated by the atomic where-clause in
      // app/api/manager/leave/route.ts, never by anything cached.
      getPendingLeaveCount(manager.id),
      // Same query the Team Quality page runs for the same manager's reports:
      // this month's rows, newest first, so the first row per employee is the
      // latest. One query for the whole team — no N+1.
      db.qualityReport.findMany({
        where: { employeeId: { in: ids }, date: inMonth },
        orderBy: { date: "desc" },
        select: { employeeId: true, qualityScore: true, date: true },
      }),
      // The manager's own row — scoped to manager.id, never to a report's id.
      loadOwnAttendance(manager.id, manager.shiftId),
    ]);

    const totalBy = new Map(totals.map((g) => [g.employeeId, g._count._all]));
    const lateBy = new Map(lates.map((g) => [g.employeeId, g._count._all]));
    const actualBy = new Map(actuals.map((a) => [a.employeeId, a._sum.unitsProduced ?? 0]));
    const targetBy = new Map(targets.map((t) => [t.employeeId, t.targetUnits]));
    const qualityBy = new Map<string, number>();
    for (const q of quality) if (!qualityBy.has(q.employeeId)) qualityBy.set(q.employeeId, q.qualityScore);

    const rows = reports.map((r) => {
      const total = totalBy.get(r.id) ?? 0;
      const late = lateBy.get(r.id) ?? 0;
      const punctuality = total > 0 ? Math.round((1 - late / total) * 100) : null;
      const actual = actualBy.get(r.id) ?? 0;
      const target = targetBy.get(r.id) ?? null;
      const prodPct = target && target > 0 ? Math.round((actual / target) * 100) : null;
      const quality = qualityBy.get(r.id) ?? null;
      return { r, punctuality, actual, target, prodPct, quality };
    });

    const totalLate = lates.reduce((s, g) => s + g._count._all, 0);
    return { manager, error: null, rows, pendingApprovals, totalLate, targetsSet: targets.length, own };
  } catch (err) {
    console.error("[manager/dashboard] failed:", err);
    return { manager: null, error: "Team data is unavailable right now." };
  }
}


export async function employeeBefore(userId: string) {
  if (!userId) return { m: null, error: null };
  try {
    // ONE lookup for both identities: the User (who receives notifications)
    // and the Employee (whose production/attendance/appraisal rows the rest of
    // this dashboard is built from). getEmployeeByClerkId() resolves through
    // User anyway and discards it, so keeping both costs nothing extra.
    //
    // This page still requires an Employee — every metric below is
    // employee-scoped — so the early return stays. It is the HR dashboard, not
    // this one, that must render for an employee-less account.
    const me = await db.user.findUnique({
      where: { clerkId: userId },
      include: { employee: true },
    });
    const employee = me?.employee;
    if (!me || !employee) return { m: null, error: null };
    const { period, monthStart, monthEnd } = currentPeriod();
    const inMonth = { gte: monthStart, lt: monthEnd };

    const [prod, target, qual, appraisal, own, consents, notifications, ownIdle] = await Promise.all([
      db.production.aggregate({
        where: { employeeId: employee.id, date: inMonth },
        _sum: { unitsProduced: true },
      }),
      db.monthlyTarget.findUnique({
        where: { employeeId_period: { employeeId: employee.id, period } },
      }),
      db.qualityReport.aggregate({
        where: { employeeId: employee.id, date: inMonth },
        _avg: { qualityScore: true },
        _count: { _all: true },
      }),
      // Most recent PUBLISHED appraisal score.
      db.appraisalScore.findFirst({
        where: {
          employeeId: employee.id,
          excluded: false,
          finalScore: { not: null },
          cycle: { published: true },
        },
        include: { cycle: { select: { period: true } } },
        orderBy: { cycle: { createdAt: "desc" } },
      }),
      // Today's row, this week's rows and the assigned shift — one nested
      // Promise.all, so this stays a single concurrent round trip.
      loadOwnAttendance(employee.id, employee.shiftId),
      // Own consent records (latest per type derived below).
      db.consentRecord.findMany({
        where: { employeeId: employee.id },
        orderBy: { givenOn: "desc" },
      }),
      // Phase 7: own notifications — unread first, then most recent.
      // Addressed by recipient User, not by Employee.
      db.notification.findMany({
        where: { recipientUserId: me.id },
        orderBy: [{ read: "asc" }, { createdAt: "desc" }],
        take: 8,
      }),
      // Their OWN idle/active totals — batched into the same round trip.
      ownIdleTotals(employee.id),
    ]);

    const latestConsent = (type: string) =>
      consents.find((c) => c.consentType === type) ?? null;

    return {
      m: {
        actual: prod._sum.unitsProduced ?? 0,
        target: target?.targetUnits ?? null,
        qualityAvg: qual._count._all > 0 ? qual._avg.qualityScore ?? null : null,
        qualityCount: qual._count._all,
        appraisalScore: appraisal?.finalScore ?? null,
        appraisalPeriod: appraisal?.cycle.period ?? null,
        today: own.today,
        punchRow: own.punchRow,
        weekStart: own.weekStart,
        weekByDate: own.weekByDate,
        idle: latestConsent("IDLE_TRACKING"),
        shift: own.shift,
        ownIdle,
        // Serialize Dates — they don't cross the RSC boundary as Date objects.
        notifications: notifications.map((n) => ({
          id: n.id,
          type: n.type,
          message: n.message,
          read: n.read,
          createdAt: n.createdAt.toISOString(),
        })),
      },
      error: null,
    };
  } catch (err) {
    console.error("[employee/dashboard] metrics failed:", err);
    return { m: null, error: "Your dashboard figures are unavailable right now." };
  }
}

